-- Generated by chardecomp: a character reconstructed from verified evidence (see spec.json and PORT.md).
local modname = minetest.get_current_modname()
local modpath = minetest.get_modpath(modname)
local function read(path)
	local f = io.open(path, "r")
	if not f then return nil end
	local s = f:read("*a")
	f:close()
	return s
end

local spec = minetest.parse_json(read(modpath .. "/spec.json"))
local Runtime = dofile(modpath .. "/runtime.lua")
local tick = 1 / (tonumber(spec.tick_rate) or 60)

-- The character as an entity. With entity_scenario.json (a recording's first snapshot and its inputs, written by
-- chardecomp) it starts as the recording did and performs the recorded inputs live, at the source tick rate.
local scen_text = read(modpath .. "/entity_scenario.json")
local entity_scen = scen_text and minetest.parse_json(scen_text) or nil

minetest.register_entity(modname .. ":character", {
	initial_properties = {
		visual = "mesh", mesh = modname .. "_character.obj", textures = {modname .. "_character.png"},
		physical = false, collisionbox = {-0.3, 0, -0.3, 0.3, 1.8, 0.3}, visual_size = {x = 1, y = 1},
	},
	on_activate = function(self)
		local s = entity_scen or {start = 0, inputs = {}, initial = {
			{x = 0.0, y = 0.0, vx = 0.0, vy = 0.0, state = 0}, {x = 60.0, y = 0.0, vx = 0.0, vy = 0.0, state = 0}}}
		self.sim = Runtime.new(spec, s.initial, s.projectile)
		self.start, self.inputs, self.acc, self.ticks = s.start, s.inputs, 0, 0
	end,
	on_step = function(self, dtime)
		self.acc = self.acc + dtime
		while self.acc >= tick do
			self.acc = self.acc - tick
			self.sim:step(tonumber(self.inputs[tostring(self.start + self.ticks)]) or -1)
			self.ticks = self.ticks + 1
		end
	end,
})

-- Validation hook: with chardecomp_selftest = true in the world's settings, replay every scenario file in
-- <world>/chardecomp/, spawn the entity and step it, write the results, and shut the server down.
if minetest.settings:get_bool("chardecomp_selftest", false) then
	local dir = minetest.get_worldpath() .. "/chardecomp"
	minetest.register_on_mods_loaded(function()
		local report = {mod = modname, spec_character = spec.character, replays = {}}
		for _, name in ipairs(minetest.get_dir_list(dir, false)) do
			local base = name:match("^(.-)%.scenario%.json$")
			if base then
				local scen = minetest.parse_json(read(dir .. "/" .. name))
				local sim = Runtime.new(spec, scen.initial, scen.projectile)
				local out = {sim:snapshot(scen.start)}
				for k = scen.start, scen["end"] - 1 do
					sim:step(tonumber(scen.inputs[tostring(k)]) or -1)
					out[#out + 1] = sim:snapshot(k + 1)
				end
				minetest.safe_file_write(dir .. "/" .. base .. ".trace.json", minetest.write_json(out))
				report.replays[#report.replays + 1] = base
			end
		end
		minetest.safe_file_write(dir .. "/report.json", minetest.write_json(report))
	end)
	-- In-game: spawn the character next to the static spawn point once the area is loaded and let it run.
	minetest.after(0.5, function()
		local pos = {x = 0, y = 10, z = 0}
		minetest.emerge_area(pos, pos, function(_, _, remaining)
			if remaining > 0 then return end
			local obj = minetest.add_entity(pos, modname .. ":character")
			minetest.after(1.0, function()
				local e = obj and obj:get_luaentity()
				local status = {spawned = e ~= nil}
				if e then
					status.ticks = e.ticks
					status.mesh = obj:get_properties().mesh
					status.snapshot = e.sim:snapshot(e.start + e.ticks)
				end
				minetest.safe_file_write(dir .. "/entity.json", minetest.write_json(status))
				minetest.request_shutdown("chardecomp self-test done", false, 0)
			end)
		end)
	end)
end
